s=open('b-body.js').read()
def rp(a,b,n=1):
    global s
    assert s.count(a)==n,(s.count(a),a[:90]); s=s.replace(a,b)
def rline(startswith, new):
    """replace the whole source line that starts with `startswith`"""
    global s
    L=s.split('\n'); idx=[i for i,l in enumerate(L) if l.startswith(startswith)]
    assert len(idx)==1,(len(idx),startswith[:60]); L[idx[0]]=new; s='\n'.join(L)
